// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const itens = $input.all().map(item => item.json);

// Dados recebidos pelo Webhook
const entradaClientes = itens.find(item =>
  Array.isArray(item.body?.clientes) || Array.isArray(item.clientes)
);

const clientes =
  entradaClientes?.body?.clientes ??
  entradaClientes?.clientes ??
  [];

// Dados produzidos pelo primeiro Code, após o HTTP Request
const entradaInvestimentos = itens.find(item =>
  Array.isArray(item.investimentos)
);

const investimentos = entradaInvestimentos?.investimentos ?? [];

if (!clientes.length) {
  throw new Error(
    "Nenhum cliente encontrado. Confira o POST do Python e a entrada 1 do Merge."
  );
}

if (!investimentos.length) {
  throw new Error(
    "Nenhum investimento encontrado. Confira o HTTP Request, o Code do CSV e a entrada 2 do Merge."
  );
}

function normalizar(valor) {
  return String(valor ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim()
    .toLowerCase();
}

function dinheiroParaNumero(valor) {
  if (typeof valor === "number") return valor;

  const texto = String(valor ?? "")
    .replace(/[^\d,.-]/g, "")
    .replace(/\./g, "")
    .replace(",", ".");

  return Number(texto) || 0;
}

const descricoes = {
  conservador: "opções voltadas à estabilidade e à preservação do capital",
  moderado: "uma combinação equilibrada de opções de renda fixa e variável",
  arrojado: "opções com maior oscilação e potencial de retorno, acompanhadas de maior risco"
};

const mensagens = clientes.map(cliente => {
  const perfil = normalizar(cliente.perfil);
  const saldo = dinheiroParaNumero(cliente.saldo);

  // O CSV precisa ter uma coluna chamada "perfil" e outra chamada "minimo".
  const compativeis = investimentos.filter(investimento =>
    normalizar(investimento.perfil) === perfil &&
    dinheiroParaNumero(investimento.minimo) <= saldo
  );

  const nomes = compativeis.map(investimento =>
    investimento.nome ??
    investimento.investimento ??
    investimento.produto ??
    "Investimento sem nome"
  );

  const primeiroNome = String(cliente.nome ?? "Cliente")
    .trim()
    .split(/\s+/)[0];

  const abertura = descricoes[perfil]
    ? `Para o seu perfil ${cliente.perfil}, faz sentido conhecer ${descricoes[perfil]}.`
    : `Vamos analisar as opções disponíveis para o seu perfil ${cliente.perfil ?? "de investidor"}.`;

  const sugestoes = nomes.length
    ? ` Considerando o saldo informado, estas opções da nossa base atendem ao valor mínimo: ${nomes.join(", ")}.`
    : " No momento, não encontrei na base uma opção desse perfil cujo valor mínimo caiba no saldo informado.";

  return {
    nome: cliente.nome,
    email: cliente.email,
    saldo: cliente.saldo,
    perfil: cliente.perfil,
    investimentos_compativeis: nomes,
    mensagem: `Olá, ${primeiroNome}! ${abertura}${sugestoes} Antes de qualquer decisão, confira as características, os riscos e as condições de cada produto.`
  };
});

// Um único item facilita devolver a lista completa no Respond to Webhook.
return mensagens.map((mensagem, indice) => ({
  json: {
    numero: indice + 1,
    nome: mensagem.nome,
    email: mensagem.email,
    saldo: mensagem.saldo,
    perfil: mensagem.perfil,
    investimentos_compativeis: mensagem.investimentos_compativeis.join(", "),
    mensagem: mensagem.mensagem
  }
}));

const respostas = $input.all();
const clientes = $("Code in JavaScript1").all();

if (respostas.length !== clientes.length) {
  throw new Error(
    `Quantidade diferente: ${clientes.length} clientes e ` +
    `${respostas.length} respostas do modelo. Confira os nós anteriores.`
  );
}

function escaparHtml(valor) {
  return String(valor ?? "").replace(/[&<>"']/g, caractere => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  })[caractere]);
}

return respostas.map((item, indice) => {
  const cliente = clientes[indice].json;
  const respostaModelo = item.json;

  const to = String(cliente.email ?? "").trim();
  const nome = String(cliente.nome ?? "").trim();
  const primeiroNome = nome.split(/\s+/)[0] || "Cliente";

  const mensagem = String(
    respostaModelo.output?.[0]?.content?.find(
      conteudo => conteudo.type === "output_text"
    )?.text ?? ""
  ).trim();

  if (!mensagem) {
    throw new Error(`O modelo não retornou texto para ${nome || `o item ${indice + 1}`}.`);
  }

  const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to);

  const subject = `${primeiroNome}, uma mensagem sobre seu perfil de investidor`;
  const text_body = mensagem;
  const html_body = `
    <div style="font-family: Arial, sans-serif; max-width: 600px; line-height: 1.6; color: #263238;">
      <p>${escaparHtml(mensagem).replace(/\n/g, "<br>")}</p>
    </div>
  `.trim();

  return {
    json: {
      ok: emailValido,
      to,
      subject,
      text_body,
      html_body,
      motivo: emailValido ? "" : "E-mail ausente ou inválido",
      meta: {
        nome,
        perfil: cliente.perfil,
        saldo: cliente.saldo
      }
    }
  };
});
